// RPT - Repeat Pattern
// The repeat pattern data type should be used where it is necessary to define the frequency at which an event is to take place. This data type provides a way to define repeat pattern codes "on the fly". The repeat pattern code is equivalent to the TQ data type, component 2, sub-component 1 (repeat pattern). The additional components define the meaning of the repeat pattern code. Components 2 - 10 are used to define relatively simple repeat patterns. Component 11 is provided to define complex repeat patterns. This data type forms a bridge between the 2.x Repeat Pattern concept from Quantity/Timing, and the Version 3.0 GTS General Timing Specification. Component 1 is the 2.x concept of repeat pattern. Components 2-7 are derived from the version 3.0 data type PIVL. Components 8-10 are derived from the version 3.0 EIVL data type. If a repeat pattern cannot be defined using components 2-10, then component 11, General Timing Specification is provided. This allows the full literal form of the version 3.0 GTS to be specified.
type RPT struct {
	RepeatPatternCode          CWE `hl7:"1"`
	CalendarAlignment          ID  `hl7:"2"`
	PhaseRangeBeginValue       NM  `hl7:"3"`
	PhaseRangeEndValue         NM  `hl7:"4"`
	PeriodQuantity             NM  `hl7:"5"`
	PeriodUnits                IS  `hl7:"6"`
	InstitutionSpecifiedTime   ID  `hl7:"7"`
	Event                      ID  `hl7:"8"`
	EventOffsetQuantity        NM  `hl7:"9"`
	EventOffsetUnits           IS  `hl7:"10"`
	GeneralTimingSpecification GTS `hl7:"11"`
}

func NewRPT() *RPT {
	return &RPT{}
}

func (d *RPT) Validate() error {

	if err := d.RepeatPatternCode.Validate(); err != nil {
		return fmt.Errorf("RPT.RepeatPatternCode: %w", err)
	}

	return nil
}

func (d *RPT) SetRepeatPatternCode(v CWE) *RPT {
	d.RepeatPatternCode = v
	return d
}

func (d *RPT) SetCalendarAlignment(v string) *RPT {
	d.CalendarAlignment = ID(v)
	return d
}

func (d *RPT) SetPhaseRangeBeginValue(v string) *RPT {
	d.PhaseRangeBeginValue = NM(v)
	return d
}

func (d *RPT) SetPhaseRangeEndValue(v string) *RPT {
	d.PhaseRangeEndValue = NM(v)
	return d
}

func (d *RPT) SetPeriodQuantity(v string) *RPT {
	d.PeriodQuantity = NM(v)
	return d
}

func (d *RPT) SetPeriodUnits(v string) *RPT {
	d.PeriodUnits = IS(v)
	return d
}

func (d *RPT) SetInstitutionSpecifiedTime(v string) *RPT {
	d.InstitutionSpecifiedTime = ID(v)
	return d
}

func (d *RPT) SetEvent(v string) *RPT {
	d.Event = ID(v)
	return d
}

func (d *RPT) SetEventOffsetQuantity(v string) *RPT {
	d.EventOffsetQuantity = NM(v)
	return d
}

func (d *RPT) SetEventOffsetUnits(v string) *RPT {
	d.EventOffsetUnits = IS(v)
	return d
}

func (d *RPT) SetGeneralTimingSpecification(v string) *RPT {
	d.GeneralTimingSpecification = GTS(v)
	return d
}

